/* Price Track frontend. Framework-free; Python serves files and proxies /api.
   Demo fixtures and browser drafts never write to Salesforce or SQLite. */
'use strict';
const $ = (s, root=document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const paths = {
 menu:'M4 6h16M4 12h16M4 18h16',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
 cases:'M3 7h18v14H3zM8 7V3h8v4M3 12h18M10 12v3h4v-3',work:'M9 4H5v17h14V4h-4M9 2h6v4H9zM8 11l2 2 5-5M8 17h7',
 check:'M5 12l4 4L19 6',shield:'M12 2l8 3v6c0 5-4 9-8 11-4-2-8-6-8-11V5zM8 12l3 3 5-6',rates:'M3 5h18v14H3zM3 9h18M7 14h3M15 14h2',
 refresh:'M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 6M4 12l2 6a7 7 0 0 0 12-1',chart:'M4 3v17h17M8 16v-5M13 16V6M18 16v-8',
 alert:'M12 3L2 21h20zM12 9v5M12 17v1',settings:'M9 3h6l1 4 4 1v7l-4 2-1 4H9l-1-4-4-2V8l4-1zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
 search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0M15 15l6 6',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4',help:'M9 9a3 3 0 1 1 5 2l-2 1v2M12 17v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
 arrow:'M5 12h14M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',plus:'M12 5v14M5 12h14',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',
 close:'M6 6l12 12M18 6L6 18',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M19 8a3 3 0 0 1 0 6M22 21v-3a4 4 0 0 0-3-4',
 link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',file:'M5 2h9l5 5v15H5zM14 2v6h5M8 12h8M8 16h6',
 layers:'M12 3L2 8l10 5 10-5zM2 12l10 5 10-5M2 16l10 5 10-5',edit:'M14 5l5 5M3 21l2-7L16 3l5 5-11 11z',save:'M4 3h13l4 4v14H3V3zM7 3v6h9V3M7 21v-8h10v8',filter:'M3 5h18l-7 8v6l-4 2v-8z',calendar:'M3 5h18v16H3zM7 2v6M17 2v6M3 10h18'
};
const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.file}"/></svg>`;
const link = (route, text, cls='') => `<a class="${cls}" href="#/${route}">${text}</a>`;
const btn = (text, action, style='', ico='', extra='') => `<button type="button" class="btn ${style}" data-action="${action}" ${extra}>${ico?icon(ico):''}${text}</button>`;
const goBtn = (text, route, style='', ico='') => `<a class="btn ${style}" href="#/${route}">${ico?icon(ico):''}${text}</a>`;
const disabled = (text, reason) => `<button type="button" class="btn" disabled title="${esc(reason)}">${esc(text)}</button>`;
const badge = (text, tone='') => `<span class="badge ${tone}">${esc(text)}</span>`;
const panel = (title, body, action='', sub='') => `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`;
const table = (headers, rows, cls='') => `<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(x=>`<td>${x ?? 'Unavailable'}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="empty"><b>No matching records</b><p>Try another filter or clear your search.</p></td></tr>`}</tbody></table></div>`;
const callout = (text, tone='') => `<div class="callout ${tone}">${icon(tone==='info'?'help':'alert')}<span>${text}</span></div>`;
const money = (n, currency='USD') => n===null || n===undefined || n==='' ? 'Unavailable' : `${new Intl.NumberFormat('en-US',{minimumFractionDigits:0,maximumFractionDigits:2}).format(Number(n))} ${esc(currency)}`;
const stats = items => `<div class="kpis">${items.map(([label,value,foot,ico,route])=>`<${route?'a':'div'} ${route?`href="#/${route}"`:''} class="kpi ${route?'card-click':''}"><span class="kpi-label">${label}${icon(ico||'chart')}</span><span class="kpi-value">${value}</span><span class="kpi-foot">${foot}</span></${route?'a':'div'}>`).join('')}</div>`;
const searchBox = (placeholder, value='', id='page-search') => `<label class="search-box">${icon('search')}<input type="search" id="${id}" aria-label="${esc(placeholder)}" placeholder="${esc(placeholder)}" value="${esc(value)}"></label>`;
const select = (id, label, values, value='') => `<select id="${id}" aria-label="${esc(label)}"><option value="">${esc(label)}</option>${values.map(x=>`<option value="${esc(x)}" ${value===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`;
const tabs = (items, active, flush=false) => `<nav class="tabs ${flush?'flush':''}" aria-label="Section navigation">${items.map(([name,route])=>link(route,esc(name),`tab ${route===active?'active':''}`)).join('')}</nav>`;
const sourceNote = (text='Design fixtures · Six fictional pricing cases') => `<div class="page-status"><span>${text}</span><span class="source-tag">Simulated workflow</span></div>`;
const rowsFooter = count => `<div class="panel-foot"><span>${count} ${count===1?'record':'records'} shown</span><span>Synthetic development data</span></div>`;
const navItems = [['Overview','overview','grid'],['Pricing Cases','cases','cases'],['Work Queue','work','work'],['Approvals','approvals','shield'],['Rate Cards','rates/client','rates'],['Renewals','renewals','refresh'],['Reports & Insights','reports/portfolio','chart'],['Exceptions','exceptions','alert'],['Administration','admin/overview','settings']];
const caseTabs = [['Summary','summary'],['Resource Ask / Estimate','estimates'],['Rates & Costs','rates'],['Pricing Versions','versions'],['Negotiation','negotiation'],['Agreement & Handoff','handoff'],['Approvals','approvals'],['Activity & Audit','activity']];
const lifecycle = ['Request','Estimate','Rates','Price','Negotiate','Approval','Agreed','Won'];
const CASES = [
 {id:'DEMO-PC-1042',account:'Northstar Retail',path:'Existing Customer / New Business',models:'T&M + FTE',owner:'Maya Shah',stage:'Waiting on Tech COE',waiting:'Tech COE',revision:7,version:'V1',versionStatus:'Approved',price:45600,cm:36.8,age:'2 days',next:'Continue estimate',section:'estimates',sourceStage:'Proposal',blocked:true},
 {id:'DEMO-PC-1043',account:'Harbor Health',path:'New Customer / New Business',models:'Program',owner:'Evan Brooks',stage:'Waiting on HR',waiting:'HR / MNH',revision:3,version:null,price:null,cm:null,age:'1 day',next:'Review missing input',section:'rates',sourceStage:'Qualification',blocked:true},
 {id:'DEMO-PC-1044',account:'Cedar Manufacturing',path:'Renewal',models:'FTE',owner:'Priya Rao',stage:'Finance review',waiting:'Finance',revision:9,version:'V1',versionStatus:'Under review',price:null,cm:null,age:'3 days',next:'Review submitted V1',section:'approvals',sourceStage:'Negotiation',blocked:false},
 {id:'DEMO-PC-1045',account:'Orbit Mobility',path:'Existing Customer / New Business',models:'Product + Program + T&M',owner:'Maya Shah',stage:'Allocation incomplete',waiting:'Pricing Operations',revision:4,version:null,price:null,cm:null,age:'4 hours',next:'Resolve allocation',section:'calculator',sourceStage:'Proposal',blocked:false},
 {id:'DEMO-PC-1046',account:'Lumen Services',path:'Existing Customer / New Business',models:'FTE',owner:'Evan Brooks',stage:'Agreement pending',waiting:'Agreement evidence',revision:6,version:'V2',versionStatus:'Approved',price:null,cm:null,age:'1 day',next:'Review agreement',section:'versions',sourceStage:'Negotiation',blocked:false},
 {id:'DEMO-PC-1047',account:'Atlas Logistics',path:'Renewal',models:'FTE',owner:'Priya Rao',stage:'Closure blocked',waiting:'Reconciliation owner',revision:5,version:'V1',versionStatus:'Eligibility unconfirmed',price:null,cm:null,age:'2 days',next:'Reconcile source',section:'integrations',sourceStage:'Closed Won',blocked:true}
];
const NORTHSTAR_SNAPSHOT = Object.freeze({version:'V1',price:48000,cm:40,submitted:'Illustrative prior submission',resources:'Two resource lines',status:'Approved fixture'});
const defaultResources = () => [{id:'RES-01',role:'Data Engineer',capability:'Data Engineering',secondary:'Data Platforms',department:'Analytics',location:'Bengaluru',country:'India',grade:'Pending',hours:[80,120,160]}, {id:'RES-02',role:'BI Analyst',capability:'Business Intelligence',secondary:'Reporting',department:'Analytics',location:'Bengaluru',country:'India',grade:'Pending',hours:[40,40,80]}];
let saved={};try{saved=JSON.parse(localStorage.getItem('pricetrack-ui-v1')||'{}');if(!saved||typeof saved!=='object'||Array.isArray(saved))saved={};}catch{}
const state={route:'overview',case:CASES[0],drafts:saved.drafts||{},notes:saved.notes||[],read:saved.read||[],ui:{},health:null,online:false,dirty:false,modalOpener:null,savedCases:[]};
const persist = () => {try{localStorage.setItem('pricetrack-ui-v1',JSON.stringify({drafts:state.drafts,notes:state.notes,read:state.read}));return true;}catch{toast('Browser storage is unavailable. Keep this tab open to retain your draft.');return false;}};
function normalizeSavedCase(row){return {id:row.case_id,account:row.account_name||'Unavailable',path:'Source opportunity',models:'Pending configuration',owner:row.opportunity_owner||'Unassigned',stage:row.status||'Requested',waiting:'Pricing Operations',revision:1,version:null,versionStatus:null,price:null,cm:null,age:'Just requested',next:'Review request',section:'summary',sourceStage:row.opportunity_stage||'Unavailable',opportunityId:row.opportunity_id,sourceName:row.opportunity_name||'Unavailable',persisted:true,createdAt:row.created_at};}
function draft(c=state.case){if(!state.drafts[c.id])state.drafts[c.id]={revision:c.revision,resources:c.id===CASES[0].id?defaultResources():[],savedAt:null,scope:'',assumptions:'',billing:'Pending confirmation',basis:'Contractual selling rate'};return state.drafts[c.id];}
const caseRoute=(section='summary',c=state.case)=>`cases/${c.id}/${section}`;
const cLink=(c,section='summary',label=c.account)=>link(caseRoute(section,c),esc(label));
const revision=()=>draft().revision;
function workflow(active=1){return `<div class="flow">${lifecycle.map((x,i)=>`<a href="#/${caseRoute(['summary','estimates','rates','calculator','negotiation','approvals','versions','integrations'][i])}" class="flow-step ${i===active?'active':i<active?'done':''}"><span class="step-num">${i<active?'✓':i+1}</span>${x}</a>`).join('')}</div>`;}
function title(name,description,ico='grid',actions=''){return `<div class="title-row"><div class="title-group"><div class="title-icon">${icon(ico)}</div><div><h1>${name}</h1><p class="subtitle">${description}</p></div></div><div class="actions">${actions}</div></div>`;}
function caseShell(section){const c=state.case;return `<div class="context-strip"><span class="case-account">${esc(c.id)} · ${esc(c.account)}</span>${badge(c.path,'outline')}${badge(c.models)}<span>Owner ${esc(c.owner)}</span><span class="spacer"></span>${c.persisted?'<span>Request saved to SQLite</span>':`<span>Working draft r${revision()}</span>${badge(state.dirty?'Unsaved browser edits':'Browser demo draft',state.dirty?'amber':'green')}`}<span>${c.persisted?'Version status: Summary / Approvals':c.version?`${c.version} · ${esc(c.versionStatus)}`:'No submitted version'}</span></div>${tabs(caseTabs.map(([n,r])=>[n,caseRoute(r)]),caseRoute(section),false).replace('class="tabs ','class="tabs case-tabs ')}`;}
function toast(text){const node=document.createElement('div');node.className='toast';node.textContent=text;$('#toasts').append(node);setTimeout(()=>node.remove(),5000);}
async function api(path,options={}){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),10000);try{const response=await fetch('/api'+path,{...options,signal:controller.signal,headers:{Accept:'application/json',...(options.headers||{})}});if(!response.ok){let detail=`Backend returned ${response.status}`;try{const data=await response.json();detail=data.error?.message||data.error||detail;}catch{}throw new Error(detail);}return await response.json();}finally{clearTimeout(timer);}}
const unavailable = (name,error) => callout(`${esc(name)} could not be loaded from the Python backend. ${esc(error.message)}. ${btn('Retry','refresh','small','refresh')}`,'error') + panel('No database rows displayed',`<div class="empty">${icon('link')}<b>Start the backend on localhost:3000</b><p>The fixture workflow pages remain available. Database pages never replace a failed request with invented records.</p></div>`);
async function checkHealth(){try{const data=await api('/health');state.health=data;state.online=data.database==='connected';$('#api-status').className=state.online?'connected':'offline';$('#api-status').textContent=state.online?'SQLite connected · Signed-in access':'Database connection not confirmed';}catch{state.online=false;$('#api-status').className='offline';$('#api-status').textContent='Backend unavailable';}}
function updateNav(){const group=state.route.split('/')[0],read=PriceTrackAuth.can('read');$('#module-nav').innerHTML=`<div class="nav-heading">Price Track</div>${navItems.filter(([name,route])=>read?['overview','cases','work','approvals','rates/client'].includes(route):route==='admin/overview').map(([name,route,ico])=>link(route,`${icon(ico)}<span>${name}</span>`,`nav-link ${group===route.split('/')[0]?'active':''}`)).join('')}${read?`<div class="nav-section">Source data</div>${link('opportunities',`${icon('link')}<span>Salesforce Opportunities</span>`,`nav-link ${group==='opportunities'?'active':''}`)}`:''}<div class="nav-section">About</div>${link('scope',`${icon('help')}<span>MVP scope</span>`,'nav-link')}<div class="nav-foot">Synthetic development workspace<br>No live enterprise integrations</div>`;}
function mvpScope(){return title('MVP scope','Available local workflows and pending company dependencies.','help')+panel('Available now',`<div class="panel-body"><p>Signed-in access, scoped source opportunities, pricing cases, resource plans, workbook calculations, saved versions, comparison, exports, negotiation history, local demo reviews, dashboard, activity history, client agreement recording and local handoff preparation.</p><p>Account directory is available to Admin. Actions depend on your role and assigned opportunity access.</p></div>`)+panel('Pending / excluded',`<div class="panel-body"><p>Company-confirmed approval policies and assigned reviewers, company SSO, live Salesforce refresh, Project Tracker connection, external project creation, notifications, renewals, exception queues, rate imports/publication and the prototype guided wizard are outside this local MVP release.</p><p>The BU Head → Finance route remains a demo. Agreement records report acceptance entered by a user; evidence is a reference only. Handoff preparation does not release a project.</p></div>`);}

let renderId=0;
async function render(){if(!PriceTrackAuth.user)return;const id=++renderId;const raw=location.hash.replace(/^#\/?/,'')||'overview';const [path,qs='']=raw.split('?');state.route=path;state.ui.params=new URLSearchParams(qs);const pieces=path.split('/');const read=PriceTrackAuth.can('read');const allowedTop=read?['overview','cases','work','approvals','opportunities','rates','scope']:['admin','scope'];const allowedCase=['summary','estimates','planning','rates','calculator','versions','compare','negotiation','approvals','activity','handoff'];if(!allowedTop.includes(pieces[0])||(pieces[0]==='rates'&&!['client','standard','compare'].includes(pieces[1]||'client'))||(pieces[0]==='cases'&&pieces[1]&&(!allowedCase.includes(pieces[2]||'summary')||pieces.length>3))||(!read&&pieces[0]==='admin'&&path!=='admin/overview')){updateNav();$('#main').innerHTML=title('Screen outside MVP scope','This screen is not included in the current release.','help')+goBtn('View MVP scope','scope','primary');return;}if(pieces[0]==='cases'&&pieces[1]?.startsWith('DEMO-PC-')){$('#main').innerHTML=title('Archived design fixture','Open a saved case from Pricing Cases.','cases')+goBtn('Pricing Cases','cases');return;}if(pieces[0]==='cases'&&pieces[1]&&!CASES.some(c=>c.id===pieces[1])){try{const result=await api('/pricing-cases?case_id='+encodeURIComponent(pieces[1]));state.savedCases=(result.pricing_cases||[]).concat(state.savedCases.filter(old=>!(result.pricing_cases||[]).some(c=>c.case_id===old.case_id)));}catch{}}const selected=CASES.find(c=>c.id===pieces[1])||state.savedCases.map(normalizeSavedCase).find(c=>c.id===pieces[1]);if(pieces[0]==='cases'&&pieces[1]&&!selected){if(id===renderId)$('#main').innerHTML=title('Case unavailable','The requested case could not be loaded from the database.','alert')+goBtn('Back to cases','cases');return;}state.case=selected||CASES[0];updateNav();let section=pieces[2]||'summary';const isCase=pieces[0]==='cases'&&pieces.length>1;state.dirty=isCase?Boolean(draft().dirty):false;const breadcrumb=`<div class="breadcrumb">ProjectTrack <span>›</span> ${link('overview','Price Track')} <span>›</span> ${isCase?`${link('cases','Pricing Cases')} <span>›</span> ${cLink(state.case,'summary',state.case.id)} <span>›</span>`:''}<span class="current">${esc(isCase?(caseTabs.find(x=>x[1]===section)?.[0]||section):navItems.find(x=>x[1]===path)?.[0]||({notifications:'Notifications',opportunities:'Salesforce Opportunities'}[pieces[0]])||pieces[0])}</span></div>`;
$('#main').innerHTML=breadcrumb+`<div class="skeleton" aria-label="Loading page"></div>`;
let content='';try{if(isCase)content=await renderCase(section);else switch(pieces[0]){case'scope':content=mvpScope();break;case'overview':content=title('Price Track Overview','Saved pricing work from your local database.','grid',btn('Refresh','refresh','','refresh')+goBtn('Source opportunities','opportunities','primary','link'))+await PricingDashboard.render();break;case'cases':content=title('Pricing Cases','Saved requests from imported opportunities.','cases',btn('Refresh','refresh','','refresh'))+await PricingWorkspace.render('cases',state.ui.params);break;case'work':content=title('Work Queue','Find saved cases and continue their next step.','work',btn('Refresh','refresh','','refresh'))+await PricingWorkspace.render('work',state.ui.params);break;case'approvals':content=title('Approval Inbox','Saved local demo requests · BU Head then Finance.','shield')+await PricingApprovals.inbox();break;case'renewals':content=title('Renewals','Outside the current signed-in MVP scope.');break;case'exceptions':content=title('Exceptions','Outside the current signed-in MVP scope.');break;case'notifications':content=title('Notifications','External notifications are not configured.');break;case'opportunities':content=await opportunities();break;case'rates':content=await ratePage(pieces[1]||'client');break;case'reports':content=title('Reports','Use Overview for saved pricing metrics.');break;case'admin':content=title('Account Directory','Local account administration.','settings')+await PriceTrackAuth.adminDirectory();break;default:content=title('Page not found','Use the navigation to return to your workspace.')+goBtn('Back to overview','overview','primary');}}catch(error){content=title('Reference data unavailable','The requested database view could not be loaded.','alert')+unavailable('Reference data',error);}
if(id!==renderId)return;$('#main').innerHTML=breadcrumb+content;$('#main').dataset.route=path;updateNav();document.title=`${$('#main h1')?.textContent||'Price Track'} · ProjectTrack`;if(state.ui.focusSearch){const input=$('#page-search');input?.focus();input?.setSelectionRange(input.value.length,input.value.length);state.ui.focusSearch=false;}}
function caseRows(data){return data.map(c=>[`${cLink(c)}<small>${c.id} · updated ${c.age} ago</small>`,`<div class="wrap">${esc(c.path)}<small>${esc(c.models)}</small></div>`,badge(c.stage,c.blocked?'amber':'purple'),`${c.version?badge(c.version+' '+(c.versionStatus||''),c.versionStatus==='Approved'?'green':'purple'):'Not submitted'}<small>Working draft r${draft(c).revision}</small>`,c.price!==null?`<strong>${money(c.price)}</strong><small>CM ${c.cm}% · Synthetic preview</small>`:'Incomplete',esc(c.waiting),cLink(c,c.section,c.next)]);}
async function renderCase(section){const c=state.case;if(c.persisted&&section==='handoff')return title('Agreement & Handoff','Record client acceptance and prepare delivery handoff.','work')+caseShell('handoff')+await PricingHandoff.render(c.id);if(c.persisted&&section==='compare')return title('Version Comparison','Review differences between two saved pricing snapshots.','layers')+caseShell('versions')+await PricingComparison.render(c.id);if(c.persisted&&section==='negotiation')return title('Negotiation','Client requests, company offers and discussion notes saved against a version.','work')+caseShell('negotiation')+await PricingNegotiation.render(c.id);if(c.persisted&&section==='activity')return title('Activity & Audit','Saved case events and retained historical records.','clock')+caseShell('activity')+await PricingActivity.render(c.id);if(c.persisted&&section==='approvals')return title('Version Approvals','Local demo · BU Head then Finance · Exact saved version.','shield')+caseShell('approvals')+await PricingApprovals.render(c.id);if(c.persisted&&section==='versions')return title('Pricing Versions','Saved pricing snapshots · Draft status · No approval implied.','layers')+caseShell('versions')+await PricingVersions.render(c.id);if(c.persisted&&section==='calculator')return title('Pricing Calculator','Workbook input mode · USD · saved backend calculations.','chart')+caseShell('calculator')+await WorkbookCalculator.render(c.id);if(c.persisted&&section==='rates')return title('Rates & Costs','Workbook cost references are used for this case.','rates')+caseShell('rates')+callout('Choose exact workbook role and experience in the calculator. The backend uses the read-only cached workbook snapshot. Seeded contractual selling-rate cards are a separate pricing basis.','info')+goBtn('Open workbook calculator',caseRoute('calculator'),'primary');if(c.persisted&&['estimates','planning'].includes(section))return title('Resource Estimates','Plan and save resources for this pricing case.','users')+caseShell('estimates')+await ResourcePlan.render(c.id);if(section==='wizard')return wizard();if(c.persisted&&section==='summary')return title('Case Summary','Current saved pricing state and demo review readiness.','cases')+caseShell('summary')+await PricingSummary.render(c.id);const names={summary:['Case Summary','Source context and pricing readiness.','cases'],estimates:['Resource Estimates','Build the resource request and resolve review checks.','users'],planning:['Resource Monthly Planning','Plan hours without assuming FTE or utilization conversions.','calendar'],rates:['Rates & Costs','Resolve a selling-rate source for each resource.','rates'],calculator:['Pricing Calculator','Inspect the saved synthetic financial fixture.','chart'],versions:['Pricing Versions','Keep submitted snapshots separate from working drafts.','layers'],compare:['Version Comparison','Compare a fixed submission with the current working draft.','layers'],negotiation:['Negotiation','Capture discussions against an exact version or revision.','work'],approvals:['Case Approvals','Review the exact submitted version.','shield'],activity:['Activity & Audit','Read-only illustrative events and browser prototype activity.','clock'],integrations:['Integrations & Source Data','Source ownership, reconciliation and handoff state.','link']};const n=names[section];if(c.persisted&&section!=='summary')return title('Pricing Case Request','This saved request is ready for the next MVP workflow piece.','cases')+caseShell('summary')+callout('Resource estimates and pricing workflow screens will be connected after this source-linked case creation slice. The request is saved in SQLite.','info')+goBtn('Back to case request',caseRoute('summary'),'primary');if(!n)return title('Page not found','Choose a case tab above.')+caseShell('summary');if(c.persisted&&section!=='summary')return title('Pricing Case Request','This saved request is ready for the next MVP workflow piece.','cases')+caseShell('summary')+callout('Resource estimates and pricing workflow screens will be connected after this source-linked case creation slice. The request is saved in SQLite.','info')+goBtn('Back to case request',caseRoute('summary'),'primary');return title(n[0],n[1],n[2],section==='summary'&&!c.persisted?goBtn('Guided flow',caseRoute('wizard')):'')+caseShell(section==='planning'?'estimates':section==='compare'?'versions':section)+sourceNote(c.persisted?`Saved SQLite case · ${esc(c.account)} · Opportunity ${esc(c.opportunityId)}`:`Design fixture · ${esc(c.account)} · Not linked to a Salesforce workbook row`)+({summary:summary,estimates:()=>resourcePage(false),planning:()=>resourcePage(true),rates:ratesCosts,calculator:calculator,versions:versions,compare:comparison,negotiation:negotiation,approvals:caseApprovals,activity:activity,integrations:integrations}[section])();}
