function resourceGrid(){const d=draft(),r=d.resources;const months=['Jan 2027','Feb 2027','Mar 2027'];return `<div class="table-wrap"><table class="resource-grid"><thead><tr>${['Resource / capability','Manage','Secondary capability*','Department*','Location*','Country*','Grade*','Employee','Rate source',...months,'Total hours'].map((x,i)=>`<th ${i===0?'class="sticky"':''}>${x}</th>`).join('')}</tr></thead><tbody>${r.length?r.map((x,i)=>`<tr><td class="sticky"><strong>${esc(x.role)}</strong><small>${esc(x.id)} · ${esc(x.capability)}</small></td><td>${btn('Details','resource-detail','small','edit',`data-index="${i}"`)}</td><td>${esc(x.secondary)}</td><td>${esc(x.department)}</td><td>${esc(x.location)}</td><td>${esc(x.country)}</td><td>${x.grade==='Pending'?badge('Required','amber'):esc(x.grade)}</td><td>Unassigned</td><td>${i===0?badge('Client card','purple'):badge('Needs lookup','amber')}</td>${x.hours.map((h,j)=>`<td><input type="number" min="0" max="10000" step="0.5" value="${h===null?'':h}" placeholder="—" aria-label="${esc(x.role)} ${months[j]} planned hours" data-hour="${i}:${j}"></td>`).join('')}<td class="numeric" data-row-total="${i}">${x.hours.some(h=>h===null)?'Incomplete':x.hours.reduce((a,b)=>a+b,0)}</td></tr>`).join(''):`<tr><td colspan="13" class="empty">No resource fixture defined for this case. Add a browser-only row to explore the interface.</td></tr>`}</tbody><tfoot><tr><td class="sticky">Visible rows total</td><td colspan="8">${r.length} resource lines · Planned hours only</td>${months.map((_,j)=>`<td class="numeric" data-month-total="${j}">${r.some(x=>x.hours[j]===null)?'Incomplete':r.reduce((s,x)=>s+x.hours[j],0)}</td>`).join('')}<td class="numeric" id="resource-grand-total">${r.some(x=>x.hours.some(h=>h===null))?'Incomplete':r.reduce((s,x)=>s+x.hours.reduce((a,b)=>a+b,0),0)}</td></tr></tfoot></table></div>`;}
