const wizardNames=['Opportunity','Scope','Resources','Rates','Commercials','Financial summary','Review & submit','Approval & closure'];
function wizard(){const step=Math.min(8,Math.max(1,parseInt(state.ui.params.get('step')||'1',10)||1)),c=state.case,d=draft();let body='';switch(step){case 1:body=panel('Opportunity & classification',`<div class="panel-body"><dl class="detail-list"><div><dt>Case / account</dt><dd>${esc(c.id)} · ${esc(c.account)}</dd></div><div><dt>Classification</dt><dd>${esc(c.path)}</dd></div><div><dt>Salesforce stage</dt><dd>${esc(c.sourceStage)}</dd></div><div><dt>Source timestamp</dt><dd>Unavailable · design fixture</dd></div><div><dt>Work types</dt><dd>${esc(c.models)}</dd></div><div><dt>Currency</dt><dd>USD · illustrative</dd></div></dl><p class="note">Source-owned fields are read-only. These cases are not linked to the Salesforce workbook records.</p></div>`);break;case 2:body=panel('Scope & commercial models',`<div class="panel-body"><div class="actions bottom-space">${c.models.split(' + ').map(x=>badge(x,'purple')).join('')}</div><div class="form-grid"><label class="field full">Scope / deliverables<textarea data-draft-field="scope" placeholder="Describe the working-draft scope">${esc(d.scope)}</textarea></label><label class="field">Pricing basis<select data-draft-field="basis"><option ${d.basis==='Contractual selling rate'?'selected':''}>Contractual selling rate</option><option ${d.basis==='Workbook target-margin pricing'?'selected':''}>Workbook target-margin pricing</option></select></label><label class="field">Billing terms<input data-draft-field="billing" value="${esc(d.billing)}"></label><label class="field full">Assumptions<textarea data-draft-field="assumptions">${esc(d.assumptions)}</textarea></label></div><p class="note">Program / Product allocation rules are pending confirmation; work type is distinct from pricing basis.</p></div>`);break;case 3:body=resourcePage(false);break;case 4:body=ratesCosts();break;case 5:body=panel('Commercials & other costs',`<div class="panel-body"><dl class="detail-list"><div><dt>Baseline price</dt><dd>${c.id===CASES[0].id?'48,000 USD · fixture':'Unavailable'}</dd></div><div><dt>Candidate price</dt><dd>${c.price!==null?money(c.price):'Unavailable'}</dd></div><div><dt>Billing terms</dt><dd>${esc(d.billing)}</dd></div><div><dt>Other-cost allocation</dt><dd>Pending confirmation</dd></div></dl><p class="note">Commercial calculation and other-cost allocation need backend support. No unsupported allocation formula is applied.</p></div>`);break;case 6:body=calculator();break;case 7:body=panel('Review exact draft r'+revision(),`<div class="panel-body">${readiness()}<div class="top-space">${disabled('Submit as next pricing version','Readiness checks and backend snapshot / task creation are not implemented.')}</div><p class="note">No formal version is created by Next or Save. Conflicting resubmissions must be blocked by the future backend.</p></div>`);break;case 8:body=callout('Agreement evidence, source Closed Won and accepted handoff are independent checks.','info')+panel('Approval & closure',`<div class="panel-body"><dl class="detail-list"><div><dt>Submitted version</dt><dd>${esc(c.version||'None')}</dd></div><div><dt>Approval</dt><dd>${esc(c.versionStatus||'Not submitted')}</dd></div><div><dt>Agreement evidence</dt><dd>Pending</dd></div><div><dt>Source stage</dt><dd>${esc(c.sourceStage)}</dd></div><div><dt>Baseline eligibility</dt><dd>Unconfirmed</dd></div><div><dt>Handoff acknowledgement</dt><dd>Not accepted</dd></div></dl><div class="actions top-space">${disabled('Mark agreed','Requires approved exact version, evidence and authenticated backend.')}${goBtn('Source detail',caseRoute('integrations'),'small')}</div><p class="note">Signed SOW timing remains pending business confirmation.</p></div>`);}
return title('Guided Pricing Flow',`Step ${step} of 8 · ${wizardNames[step-1]} · Same case and working draft.`, 'cases',goBtn('Return to case',caseRoute('summary')))+caseShell('wizard')+`<nav class="wizard-stepper" aria-label="Guided flow steps">${wizardNames.map((n,i)=>link(caseRoute('wizard')+'?step='+(i+1),`${i+1}<b>${n}</b>`,`wizard-step ${step===i+1?'active':''}`)).join('')}</nav>`+sourceNote()+body+`<div class="panel"><div class="panel-foot"><span>Browser prototype · draft r${revision()} · No implicit submission</span><div class="actions">${step>1?goBtn('Back',caseRoute('wizard')+'?step='+(step-1)):''}${btn('Save Draft','save-draft','','save')}${step<8&&step!==7?goBtn('Next: '+wizardNames[step],caseRoute('wizard')+'?step='+(step+1),'primary','arrow'):step===7?goBtn('Preview closure screen',caseRoute('wizard')+'?step=8'):''}</div></div></div>`;}
function markDirty(){const d=draft();d.dirty=true;d.financialStale=true;state.dirty=true;const status=$('#draft-save-status');if(status)status.textContent=`Unsaved browser edits · r${d.revision} · Reviews invalidated`;}
function saveDraft(){const d=draft();if(d.dirty)d.revision++;d.dirty=false;state.dirty=false;d.savedAt=new Date().toISOString();if(persist())toast(`Working draft r${d.revision} saved in this browser only. No version created.`);render();}
function modal(name,body,actions='',drawer=false){closeModal(false);state.modalOpener=document.activeElement;const host=$('#overlay');host.innerHTML=`<div class="modal-scrim ${drawer?'drawer-scrim':''}"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-head"><h2 id="dialog-title">${esc(name)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div><div class="dialog-actions">${btn('Close','close-modal')}${actions}</div></section></div>`;document.body.style.overflow='hidden';const first=$('.dialog input,.dialog textarea,.dialog select,.dialog button');first?.focus();}
function closeModal(focus=true){$('#overlay').innerHTML='';document.body.style.overflow='';if(focus)state.modalOpener?.focus?.();}
function csvDownload(name,headers,rows){const field=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+\-@\t\r]/,"'$&")+'"';const csv='\uFEFF'+[headers,...rows].map(row=>row.map(field).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Exported visible synthetic data.');}
function exportPage(){const tables=[...document.querySelectorAll('main table')];if(!tables.length){toast('No table is displayed on this view.');return;}const all=tables.flatMap(t=>[...t.rows].map(r=>[...r.cells].map(c=>c.innerText.replace(/\n/g,' · '))));csvDownload('price-track-synthetic-view.csv',all[0],all.slice(1));}
function setQuery(changes){const p=new URLSearchParams(state.ui.params);for(const [k,v]of Object.entries(changes)){if(v===null||v==='')p.delete(k);else p.set(k,v);}location.hash='/'+state.route+(p.size?'?'+p:'');}
function objectDetail(obj){return `<dl class="detail-list">${Object.entries(obj).map(([k,v])=>`<div><dt>${esc(k.replace(/_/g,' '))}</dt><dd>${esc(v===null||v===''?'Unavailable':v)}</dd></div>`).join('')}</dl>`;}
const actions={
 profile:()=>PriceTrackAuth.showAccount(),
 refresh:async()=>{await checkHealth();render();},
 'global-search':()=>{modal('Search pricing cases',`<label class="field">Case or account<input id="global-search-input" placeholder="Account, opportunity, owner or case ID…"></label><p class="note">Searches saved pricing cases by account, opportunity, owner or case ID. Use Salesforce Opportunities to browse imported source records.</p>`,btn('Search','submit-global-search','primary','search'));},
 'submit-global-search':()=>{const q=$('#global-search-input').value.trim();closeModal();location.hash='/cases'+(q?'?q='+encodeURIComponent(q):'');},
 help:()=>{location.hash='/scope';},
 'legacy-demo-profile':()=>modal('Demo identity',`<div class="actions"><span class="avatar">MS</span><div><h3>Maya Shah</h3><p class="small muted">Pricing Operations · fictional identity</p></div></div><p class="note">Finance screens are explicitly labeled view previews. This frontend does not authenticate a user or enforce authorization. Confidential employee costs are never included.</p>`,btn('Reset browser demo','confirm-reset','danger')),
 'confirm-reset':()=>modal('Reset browser demo?',`<p class="small">This clears browser drafts, negotiation notes and notification read state. Your SQLite database is unaffected.</p>`,btn('Reset local demo','reset-demo','danger')),
 'reset-demo':()=>{state.drafts={};state.notes=[];state.read=[];state.dirty=false;persist();closeModal();render();toast('Browser demo reset.');},
 'save-draft':saveDraft,
 'table-view':()=>{state.ui.cards=false;render();},'cards-view':()=>{state.ui.cards=true;render();},
 'clear-filters':()=>{location.hash='/'+state.route;},
 'resource-detail':el=>{const i=Number(el.dataset.index),r=draft().resources[i];state.ui.resourceIndex=i;modal('Resource details · '+r.id,`<div class="form-grid">${[['role','Role',r.role],['capability','Primary capability',r.capability],['secondary','Secondary capability',r.secondary],['department','Department',r.department],['location','Location',r.location],['country','Country',r.country],['grade','Grade',r.grade==='Pending'?'':r.grade]].map(([id,label,value])=>`<label class="field">${label}<input id="resource-${id}" value="${esc(value)}" required></label>`).join('')}</div><p class="note">Edits affect this browser draft only and invalidate its financial preview and review checks. Employee costs are not included.</p>`,btn('Apply to draft','apply-resource','primary'),true);},
 'apply-resource':()=>{const r=draft().resources[state.ui.resourceIndex];const fields=['role','capability','secondary','department','location','country','grade'];for(const key of fields){if(!$('#resource-'+key).value.trim()){$('#resource-'+key).reportValidity();return;}}fields.forEach(key=>r[key]=$('#resource-'+key).value.trim());markDirty();closeModal();render();toast('Resource updated in the working draft.');},
 'add-resource':()=>{draft().resources.push({id:'RES-'+String(draft().resources.length+1).padStart(2,'0'),role:'New resource',capability:'Pending',secondary:'Pending',department:'Pending',location:'Pending',country:'Pending',grade:'Pending',hours:[null,null,null]});markDirty();render();toast('Added an incomplete browser-only row. Enter dimensions and hours.');},
 'export-resources':()=>csvDownload('price-track-resource-draft.csv',['Resource','Role','Primary capability','Secondary capability','Department','Location','Country','Grade','Jan 2027 hours','Feb 2027 hours','Mar 2027 hours'],draft().resources.map(r=>[r.id,r.role,r.capability,r.secondary,r.department,r.location,r.country,r.grade,...r.hours])),
 'request-estimate':()=>modal('Estimate request readiness',callout('No request was sent. Tech COE and BU request endpoints are not implemented.','info')+readiness()+`<p class="note">When integrated, this action must route the exact saved draft revision to the assigned reviewers. It must not automatically approve an estimate.</p>`,goBtn('Review workflow','work')),
 'rate-provenance':()=>modal('Rate source requirements',`<p class="small">The resolution rows are UI examples, not matched rates. A valid lookup needs account scope, role / level, location, currency, unit, effective period and publication status.</p><p class="note">The reference datasets are available in Rate Cards. No invented numeric rate is used in this case.</p>`,goBtn('Open client references','rates/client'),true),
 'hr-detail':()=>modal('HR-208 · Missing cost input',`<dl class="detail-list"><div><dt>Owner</dt><dd>HR / MNH queue</dd></div><div><dt>Location</dt><dd>Delaware</dd></div><div><dt>State</dt><dd>Awaiting validated response</dd></div><div><dt>Next validation</dt><dd>Finance</dd></div></dl><p class="note">This unsized example is separate from the two-row Northstar planning fixture. No cost or selling price is inferred. External request submission is not configured.</p>`,disabled('Send request','External HR integration is not implemented.'),true),
 'submission-readiness':()=>modal('Review working draft r'+revision(),readiness()+`<p class="note">Blocked: current reviews, validated source matches, a pricing-engine output and confirmed route are not available. Only deliberate backend submission should create Vn and its tasks.</p>`,disabled('Submit as next version','Readiness and immutable submission APIs required.')),
 'why-price':()=>modal('Why this price?',`<p class="small">For Northstar, the UI brief supplies an illustrative 48,000 USD approved V1 price and a 45,600 USD candidate draft price, with CM 40% and 36.8% respectively.</p><p class="note">These values are display fixtures, not results from resource hours or rate cards. The frontend does not infer confidential costs or implement the Margin Calculator workbook.</p>`,goBtn('Source assumptions',caseRoute('calculator')+'?view=sources'),true),
 snapshot:()=>modal('Submitted snapshot · '+(state.case.version||'None'),state.case.id===CASES[0].id?objectDetail(NORTHSTAR_SNAPSHOT):`<p class="small">${esc(state.case.id)} · ${esc(state.case.version||'No submitted version')} · ${esc(state.case.versionStatus||'Not submitted')}</p><p class="note">No numeric snapshot fixture is supplied for this case.</p>`, '',true),
 'rejected-snapshot':()=>modal('Lumen V1 · Rejected',`<p class="small">The rejected V1 remains in submission history. Lumen V2 is separately approved in the design fixture. Numeric values and decision rationale are unavailable.</p>`, '',true),
 'restore-draft':()=>modal('Restore snapshot to working draft?',`<p class="small">The brief does not provide the full submitted resource, rate and assumption snapshot. Restoring partial inputs would create misleading draft content.</p><p class="note">A complete backend snapshot and deliberate confirmation are required. No approval will ever be copied to a draft.</p>`,disabled('Restore snapshot','Complete immutable input snapshot unavailable.')),
 'record-discussion':()=>modal('Record discussion',`<div class="form-grid"><label class="field">Event type<select id="discussion-type">${['Client Ask','Company Offer','Internal Note','Clarification','Approval Feedback'].map(t=>`<option>${t}</option>`).join('')}</select></label><label class="field">Reference<input readonly value="Draft r${revision()} · Not submitted"></label><label class="field full">Notes<textarea id="discussion-note" placeholder="Record context and rationale. Do not enter confidential costs." maxlength="2000" required></textarea></label></div><p class="note">Saved in this browser only. No formal version is created.</p>`,btn('Save local note','save-discussion','primary')),
 'save-discussion':()=>{const input=$('#discussion-note'),text=input.value.trim();if(!text){input.setCustomValidity('Enter discussion notes.');input.reportValidity();input.addEventListener('input',()=>input.setCustomValidity(''),{once:true});return;}state.notes.push({caseId:state.case.id,type:$('#discussion-type').value,text,time:new Date().toISOString()});persist();closeModal();render();toast('Discussion saved in this browser.');},
 'exception-detail':el=>{const e=EXCEPTIONS.find(x=>x[0]===el.dataset.id);if(!e)return;modal(e[0]+' · '+e[2],`<dl class="detail-list"><div><dt>Case</dt><dd>${esc(CASES[e[1]].id)}</dd></div><div><dt>Owner / queue</dt><dd>${esc(e[4])}</dd></div><div><dt>Status</dt><dd>${esc(e[5])}</dd></div><div><dt>Severity</dt><dd>${esc(e[3])}</dd></div></dl><p class="note">Illustrative operational issue. Resolution requires a note, validation and an authenticated backend action. Handoff attempts do not mean acceptance.</p>`,goBtn('Open case section',caseRoute(e[6],CASES[e[1]]),'primary'),true);},
 'read-all':()=>{state.read=NOTIFICATIONS.map((_,i)=>i);persist();render();},
 'read-notification':el=>{state.read=[...new Set([...state.read,Number(el.dataset.index)])];persist();render();},
 'notification-open':el=>{const i=Number(el.dataset.index),n=NOTIFICATIONS[i];state.read=[...new Set([...state.read,i])];persist();location.hash='/'+caseRoute(n[3],CASES[n[2]]);},
 'opportunity-page':el=>setQuery({offset:el.dataset.offset}),
 'opportunity-detail':el=>{const r=state.ui.opportunityRows[Number(el.dataset.index)];if(!r)return;modal('Source opportunity details',callout('Read-only local SQLite snapshot. No live Salesforce refresh or case linkage.','info')+objectDetail(r),'',true);}, 'request-pricing':el=>{const id=el.dataset.opportunityId;const row=state.ui.opportunityRows.find(r=>r.opportunity_id===id);if(!row)return;modal('Request pricing',`<p class="small">Create a pricing request linked to this imported opportunity?</p><dl class="detail-list"><div><dt>Opportunity</dt><dd>${esc(row.opportunity_name||id)}</dd></div><div><dt>Opportunity ID</dt><dd>${esc(id)}</dd></div><div><dt>Account</dt><dd>${esc(row.account_name||'Unavailable')}</dd></div><div><dt>Source stage</dt><dd>${esc(row.stage||'Unavailable')}</dd></div></dl><p class="note">This creates one persistent local case for this opportunity. It does not send anything to Salesforce.</p>`,btn('Create pricing request','create-pricing-case','primary','plus',`data-opportunity-id="${esc(id)}"`));},
 'create-pricing-case':async el=>{const id=el.dataset.opportunityId;if(!id)return;el.disabled=true;el.textContent='Creating…';try{const result=await api('/pricing-cases',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({opportunity_id:id})});const saved=result.pricing_case;if(!saved?.case_id)throw new Error('Backend response did not include the saved case.');state.savedCases=[saved,...state.savedCases.filter(c=>c.case_id!==saved.case_id)];closeModal();location.hash='/'+caseRoute('summary',normalizeSavedCase(saved));toast(result.existing?'A pricing request already existed. Opened the saved case.':'Pricing request saved in SQLite.');}catch(error){el.disabled=false;el.textContent='Create pricing request';toast(error.message||'Could not create the pricing request.');}},

 'reference-detail':el=>{const r=state.ui.rateRows[Number(el.dataset.index)];if(!r)return;modal('Selling-rate provenance',objectDetail(r)+`<p class="note">Reference status is shown as seeded. This is not evidence of Finance publication or a validated case match.</p>`,'',true);},
 'export-page':exportPage,
 'close-modal':()=>closeModal()
};
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(target&&!target.disabled){const action=actions[target.dataset.action];if(action){event.preventDefault();Promise.resolve(action(target)).catch(err=>toast('Action failed: '+err.message));}}const route=event.target.closest('[data-route]');if(route)location.hash='/'+route.dataset.route;if(event.target.classList.contains('modal-scrim'))closeModal();if(event.target.closest('#overlay a'))closeModal();});
let searchTimer;document.addEventListener('input',event=>{const t=event.target;if(t.matches('[data-hour]')){const [i,j]=t.dataset.hour.split(':').map(Number);if(!t.validity.valid)return;const value=t.value===''?null:Number(t.value);draft().resources[i].hours[j]=value;markDirty();const rows=draft().resources;document.querySelectorAll('[data-row-total]').forEach(n=>{const row=rows[Number(n.dataset.rowTotal)];n.textContent=row.hours.some(h=>h===null)?'Incomplete':row.hours.reduce((a,b)=>a+b,0);});document.querySelectorAll('[data-month-total]').forEach(n=>{const j=Number(n.dataset.monthTotal);n.textContent=rows.some(r=>r.hours[j]===null)?'Incomplete':rows.reduce((s,r)=>s+r.hours[j],0);});$('#resource-grand-total').textContent=rows.some(r=>r.hours.some(h=>h===null))?'Incomplete':rows.reduce((s,r)=>s+r.hours.reduce((a,b)=>a+b,0),0);}
if(t.matches('[data-draft-field]')){draft()[t.dataset.draftField]=t.value;markDirty();}
if(t.id==='page-search'){clearTimeout(searchTimer);const route=state.route;searchTimer=setTimeout(()=>{if(state.route!==route)return;state.ui.focusSearch=true;setQuery({q:t.value,offset:null});},350);}});
document.addEventListener('change',event=>{const t=event.target;const map={'case-path':'path','case-stage':'stage','case-owner':'owner','source-stage':'stage','rate-currency':'currency','rate-date':'date'};if(map[t.id])setQuery({[map[t.id]]:t.value,offset:null});if(t.id==='pricing-basis'){draft().basis=t.value;markDirty();toast('Pricing basis changed in draft only. No formula executed.');}if(t.matches('select[data-draft-field]')){draft()[t.dataset.draftField]=t.value;markDirty();}});
document.addEventListener('keydown',event=>{if(!$('#overlay .dialog'))return;if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'){const focusable=[...$('#overlay').querySelectorAll('button:not(:disabled),a[href],input,textarea,select,[tabindex="0"]')];const first=focusable[0],last=focusable.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}if(event.key==='Enter'&&event.target.id==='global-search-input')actions['submit-global-search']();});
$('#nav-toggle').innerHTML=icon('menu');$('#nav-toggle').addEventListener('click',()=>{if(matchMedia('(max-width:1050px)').matches){document.body.classList.toggle('nav-open');$('#nav-toggle').setAttribute('aria-expanded',String(document.body.classList.contains('nav-open')));}else{document.body.classList.toggle('nav-collapsed');$('#nav-toggle').setAttribute('aria-expanded',String(!document.body.classList.contains('nav-collapsed')));}});
const headerIcons=[['global-search','search'],['help','help']];headerIcons.forEach(([a,i])=>{document.querySelector(`header [data-action="${a}"]`).innerHTML=icon(i);});
$('#rail-icons').innerHTML=link('scope',icon('rates'),'icon-button active');
window.addEventListener('hashchange',()=>{clearTimeout(searchTimer);closeModal(false);document.body.classList.remove('nav-open');render();});
window.addEventListener('beforeunload',event=>{if(Object.values(state.drafts).some(d=>d.dirty)){event.preventDefault();event.returnValue='';}});
PriceTrackAuth.ready.then(user=>{if(!user)return;if(user.role==='Admin'&&!location.hash.startsWith('#/admin'))location.hash='/admin/overview';render();checkHealth();});
